from pathlib import Path
import base64,gzip
ROOT=Path(__file__).resolve().parent
PARTS=ROOT/'index_parts'
DATA=''''''

def apply_v11():
    files=sorted(PARTS.glob('index.part.*'))
    if not files:return
    html=gzip.decompress(base64.b64decode(DATA)).decode('utf-8')
    files[0].write_text(html,encoding='utf-8')
    for p in files[1:]:
        try:p.unlink()
        except FileNotFoundError:pass
    print('MINUKIMI v1.1 product shell applied')
apply_v11()
